#include <iostream>
#include <vector>

int registrar_y_medir(const std::vector<int>& antes, std::vector<int>& actual) {
    actual.push_back(7);
    return static_cast<int>(antes.size());
}

int main() {
    // Escribe tu pregunta y tus predicciones antes de ejecutar.
    std::vector<int> entrada{2, 5};
    std::vector<int> destino{9};
    const int separados = registrar_y_medir(entrada, destino);
    std::cout << "Separados=" << separados << ";Entrada=" << entrada.size()
              << ";Actual=" << destino.size() << '\n';

    std::vector<int> compartido{2, 5};
    const int juntos = registrar_y_medir(compartido, compartido);
    std::cout << "Compartido=" << juntos << ";Actual=" << compartido.size() << '\n';
    return 0;
}

int registrar_y_medir(const std::vector<int>& antes, std::vector<int>& actual) {
    const int cantidad_anterior = static_cast<int>(antes.size());
    actual.push_back(7);
    return cantidad_anterior;
}
